//##UTILS

//Object Query
//Matrix uses a version of V8 that doesn't support Optional Chaining
//Using a wrapper function (fn) here to ensure the script doesn't crash if accessing a deeply nested key that doesn't exist.
const objQuery = <T>(
    fn: () => T
): T | false => {
    try {
        const val = fn();
        
        //if not found, return false
        if (val === undefined || val === null) return false;

        return val;
        
    } catch (e) {
        //catch errors and return false
        return false;
    }
};

//Variable is String
const isString = (value: unknown): value is string => 
    typeof value === 'string' || value instanceof String;

//Safe HTML 
//Escape double quotes
const escapeDoubleQuote = (string: string): string => 
    string.replace(/\"/g, '&quot;');

//Encode HTML
const escapeHtml = (str: string | null | undefined): string => {
    if (!str) return '';
    const map: Record<string, string> = {
        '<': '&lt;',
        '>': '&gt;',
    };
    return str.replace(/[<>]/g, (m) => map[m]);
};

//Check of locks are acquired
const isLocksAcquired = (wrapperHtml: string | null | undefined | false): boolean => {
    if (!wrapperHtml) return false;

    const patterns = [
        '<select(?=[^>]*?class=["\'][^"\']*?sq-form-field)',                                                // Select List
        '<input(?=[^>]*?type=["\']checkbox["\'])(?=[^>]*?class=["\'][^"\']*?sq-form-field)',                // Select Checkbox
        '<input(?![^>]*?disabled)(?=[^>]*?type=["\']text["\'])(?=[^>]*?class=["\'][^"\']*?sq-form-field)',  // Text - type: text, or Asset Finder
        '<textarea(?![^>]*?disabled)(?=[^>]*?class=["\'][^"\'][^>]*?sq-form-field)',                       // Text - textareas / multi-line 
        'class=["\'][^"\']*?sq-wysiwyg-standalone-body[^"\']*?["\'](?=[\\s\\S]*?<textarea)'                 // WYSIWYG editors
    ];
    
    const combinedRegex = new RegExp(patterns.join('|'), 'im');

    return combinedRegex.test(wrapperHtml);
};

//Extract input value from field html
const getInputValue = (html: string | null | undefined): string => {
    const match = (html || "").match(/value\s*=\s*["']([^"']*?)["']/i);
    return match ? match[1] : "";
};


//## STORE DATA FORMAT

interface MetadataItem {
    fieldid: string | number;
    value: unknown;
}

interface MetadataHashmapValue {
    value: unknown;
    name: string;
}

// Generate Metadata Hashmap
const cctMetadataHashmap = (
    metadata: Record<string, MetadataItem>
): Record<string, MetadataHashmapValue> => {
    return Object.fromEntries(
        Object.entries(metadata).map(([key, item]) => [
            item.fieldid, 
            { value: item.value, name: key }
        ])
    );
};


interface ControlFieldConfig {
    id: string | number;
    extraClasses: string;
    html: string;
}

interface SectionData {
    id: string;
    extraClass: string;
    fields: ControlFieldConfig[];
}

// Hidden Control Section Data
const cctControlSectionData = (): SectionData | false => {
    
    // All fields that start with cct-control.
    const cctControlFields = Object.keys(store.asset.metadata).filter(item => item.startsWith("cct-control."));
    
    if (cctControlFields.length) {
        
        const assetId = store.asset.assetid;
        
        // FIXED BUG: Added [0] index to cctControlFields to correctly grab the first matching field key
        const firstFieldKey = cctControlFields[0];
        const sectionId = `%globals_asset_parent:${store.asset.metadata[firstFieldKey].fieldid}%`;
        
        // Section data structure explicitly typed
        const sectionData: SectionData = {
            id              : sectionId,
            extraClass      : 'hidden',
            fields          : [],
        };
        
        // Loop through fields to find id & html
        cctControlFields.forEach((fieldName) => {
            
            const fieldId = store.asset.metadata[fieldName].fieldid;
            const fieldConfig: ControlFieldConfig = {
                id          : fieldId,
                extraClasses: 'bg-alert',
                html        : `<input type="text" name="container_${assetId}_metadata_field_text_${fieldId}_value" value="%globals_asset_metadata_${fieldName}:${assetId}^escapehtml%" class="form-control sq-form-field" id="container_${assetId}_metadata_field_text_${fieldId}_value">`,
            };
            
            // Add field to sectionData
            sectionData.fields.push(fieldConfig);
        });
        
        return sectionData;
    }
    
    return false;            
};


//#GLOBAL STORE

// 1. Interfaces for the Data Structures
interface AssetAttributes {
    attributes: {
        value: {
            template: string;
            container_id?: string;
        };
    };
}

interface AssetData {
    assetid: string | number;
    metadata: Record<string, MetadataItem>;
    attributes: AssetAttributes;
}

interface FieldData {
    id: string | number;
    html?: string;
    retired?: boolean;
}

interface SectionInput {
    id: string | number;
    activeHeading?: string | number;
    sort?: boolean;
    sortRef?: string | number;
    fields: FieldData[];
}

interface InitDataInput {
    assetData: string; // JSON string of AssetData
    sections: SectionInput[];
    conditionalVisibility?: Array<{ trigger: string | number }>;
    [key: string]: unknown; // For any other properties passed in data
}

interface StoreHasState {
    visibility: boolean;
    sort: boolean;
    retired: boolean;
    locks: boolean;
}

interface StoreStructure extends Omit<InitDataInput, 'assetData'> {
    asset: AssetData;
    has: StoreHasState;
    cctId?: string;
    metadataHashMap?: Record<string, MetadataHashmapValue>;
    visibilityTriggers?: string[];
    url?: string;
    sections: SectionInput[]; 
    feedback?: {};
    guideUrl?: string;
    inlineDescription?: boolean;
}

// 2. Global Store Variable
let store: StoreStructure = {} as StoreStructure;

// 3. InitStore Function Implementation
const initStore = (data: InitDataInput): void => {
    
    //Data variables
    const asset: AssetData = JSON.parse(data.assetData);
    const assetId = asset.assetid.toString();

        //Adjust & Validate Store
        
            //## 1. cct level
            
                //Store data in global store
                store = {
                    ...data,
                    asset,
                    has                     : {
                        visibility  : false,
                        sort        : false,
                        retired     : false,
                        locks       : false,
                    },
                };
                
                //Easy access of CCT Id
                store.cctId = asset.attributes.attributes.value.template;
                
                //Metadata Hashmap
                store.metadataHashMap = cctMetadataHashmap(asset.metadata);

                
                //Conditional Visibility
                store.has.visibility = !!objQuery(() => data["conditionalVisibility"]);
                if(store.has.visibility && data.conditionalVisibility) {
                  store.visibilityTriggers = data.conditionalVisibility.map((rules) => String(rules.trigger));  
                }
                
                //Component URL
                const containerIdAttr = objQuery(() => asset.attributes.attributes.value.container_id);
                const hash = containerIdAttr ? `#${containerIdAttr.replace(/\\/g, '\\\\')}` : ``;
                store.url = `%globals_asset_parent:${assetId}^as_asset:asset_parent^as_asset:asset_url%/_nocache${hash}`;
                
                //Locks (check first form element in cct)
                const firstFieldHtml = objQuery(() => data.sections[0].fields[0].html);
                store.has.locks = isLocksAcquired(firstFieldHtml);
            
            //## 2. section level
            data.sections.forEach(function(section, index) {
                
                //validate activeHeading - check if the activeHeading id exists in the fields
                const activeHeading = objQuery(() => section.activeHeading);
                if(activeHeading){
                    const activeHeadingField = section.fields.some(function(field) {
                        return field.id.toString() === activeHeading.toString();
                    });
                    
                    // Fallback typing alignment for safety
                    if (store.sections[index]) {
                        store.sections[index].activeHeading = activeHeadingField ? activeHeading.toString() : 'false';
                    }
                }
                
                //sort fields
                if(objQuery(() => section.sort) === true){
                    
                    if (store.sections[index]) {
                        //adjust sortRef (sortRef default value is section id)
                        const rawSortRef = objQuery(() => section.sortRef);
                        store.sections[index].sortRef = rawSortRef && String(rawSortRef).length ? String(rawSortRef) : section.id.toString();
                    }
                                
                    //adjust has.sort for the cct (if one sort is found in any section, the cct has sort)
                    if (!store.has.sort) {
                        store.has.sort = true;
                    }
                }
                
            //## 3. field level
                //adjust has retired for cct. Skip if already found one retired field
                if (!store.has.retired) {
                    const retiredFound = section.fields.some(function(field) {
                        return objQuery(() => field.retired) === true;
                    });

                    if (retiredFound) store.has.retired = true;
                }
                
            });

        
            //## 4. CCT Control Section (check if this CCT has a CCT Control section, if found add section data to store.sections)
            const controlSectionData = cctControlSectionData();
            if(controlSectionData){
                // Pushing runtime transformed data into sections array
                (store.sections as unknown[]).push(controlSectionData);
            }
        
};


//## FIELD HTML SELECT

interface SelectOption {
    value: string | number;
    label: string;
}

//Option HTML
const cctSelectOptionsHTML = (
    inputValue: string | number, 
    optionsArray: SelectOption[]
): string => {
    const html = optionsArray.map(option => {
            const selected = inputValue == option.value ? ` selected` : ``;
            return `<option${selected} value="${option.value}">${option.label}</option>`;
        }).join('');
    
    return html;
};


//Build Select Options
const cctCustomSelectOptionsBuilder = (
    inputHtml: string | null | undefined, 
    inputId: string | number, 
    optionsArray: SelectOption[]
): string => {
    let html = ``;
    const inputValue = getInputValue(inputHtml);

    // Locks acquired
    if (store.has.locks) {

        // Build Select HTML
        html = `<span class="cct-html-select__md-field hidden">${inputHtml || ""}</span>
                <select name="cct-html-select__select-${inputId}" class="cct-html-select__select">
                    ${cctSelectOptionsHTML(inputValue, optionsArray)}
                </select>
                `;

    } else {
        // Locks not acquired
        const selectedOption = optionsArray.find(option => option.value == inputValue);
        if(selectedOption){
            html = `<span class='cct-selecthtml-label'>${selectedOption.label}</span>`;
        }
    }

    return html;
};


//## FIELD HTML

interface FieldHtmlData {
    id: string | number;
    html?: string;
    retired?: boolean;
    required?: 'soft' | string;
    extraClass?: string;
    toggleAnimation?: boolean;
    htmlSelect?: {
        name?: string;
        options?: SelectOption[];
    };
}

const cctFieldHtml = (
    data: FieldHtmlData, 
    activeHeadingId: string | number | undefined | null
): string => {
     
    //variables
    const id = data.id.toString();
    const isRetired = objQuery(() => data.retired) === true;
    
    // Fallback in case the metadataHashMap doesn't contain the field ID
    const metadataItem = store.metadataHashMap ? store.metadataHashMap[id] : undefined;
    const name = metadataItem ? metadataItem.name : '';
    const value = metadataItem && typeof metadataItem.value === 'string' ? metadataItem.value : '';
    
    const isSoftRequired = objQuery(() => data.required) === 'soft';
    const isHtmlSelect = objQuery(() => data.htmlSelect);
    const isCustomHtmlSelect = isHtmlSelect && objQuery(() => data.htmlSelect!.name);
    const isNoToggleAnimation = "toggleAnimation" in data && data.toggleAnimation === false;
    
    //Row classes
    const rowClassesArray: string[] = [
        //required (strong Metadata field setting)
        `%globals_asset_data_attributes:${id}^json_decode^index:required^index:value^eq:true:required:%`,
    ];
    
    //active heading
    if (activeHeadingId?.toString() === id) rowClassesArray.push('activeHeading');
    //retired
    if (isRetired) rowClassesArray.push('sq-metadata-settings-row--retired hidden');
    //extra class
    const extraClass = objQuery(() => data.extraClass);
    if (extraClass) rowClassesArray.push(extraClass);
    //Visibility trigger
    const visibilityTriggers = objQuery(() => store.visibilityTriggers);
    if (visibilityTriggers && visibilityTriggers.includes(id)) rowClassesArray.push('visibility-trigger');
    //Soft Required
    if (isSoftRequired) rowClassesArray.push('required-soft');
    //HTML Select
    if (isHtmlSelect) rowClassesArray.push("cct-html-select");
    if (isCustomHtmlSelect && data.htmlSelect?.name) rowClassesArray.push(`cct-html-select--${data.htmlSelect.name}`);
    //Toggle Animation
    if (isNoToggleAnimation) rowClassesArray.push("cct-no-toggle-animation");
    
    //All classes string
    const rowClasses = ` ${rowClassesArray.join(' ')}`;
        
    //Conditional/Reusable HTML parts
    const retiredLabelHtml = isRetired ? `<span class="rounded bg-warning small text-white text-nowrap d-inline-block mt-2 px-2">Retired</span>` : ``;
    const requiredErrorHtml = value.trim().length ? `` : `<br><span class="sq-metadata-warning sq-backend-warning">Currently empty</span>`;
    const requiredLabelHtml = `
            <span title="This field is required">
                <span class="sq-metadata-settings-row__field-name" id="${id}">
                    {globals_asset_data_attributes:${id}^json_decode^index:friendly_name^index:value}
                </span> 
                <span class="sq-backend-warning">*</span>
            </span>
        `;

    // Extract options conditionally for the builder snippet
    const selectOptions = data.htmlSelect?.options || [];
    
    //row html
    const html  = ` 
                <tr class="sq-backend-row sq-metadata-settings-row${rowClasses}" data-sq-id="${id}">
                    <td class="sq-backend-field">
                        <span class="sq-backend-field-label">
                            %globals_asset_data_attributes:${id}^json_decode^index:required^index:value^eq:true:${requiredLabelHtml}:${isSoftRequired ? requiredLabelHtml : `{globals_asset_data_attributes:${id}^json_decode^index:friendly_name^index:value}`}%
                            <br>
                            <a title="Find in Asset Map" class="js_sq-locate-asset-in-map sq-backend-note sq-backend-note-light" data-asset-id="${id}">
                                ${name} #${id}
                            </a>
                            %globals_asset_data_attributes:${id}^json_decode^index:required^index:value^eq:true:${requiredErrorHtml}:${isSoftRequired ? requiredErrorHtml : ``}%
                        </span>
                    </td>
                    <td class="sq-backend-data">
                        <div class="sq-backend-data__input-wrapper" data-name="${escapeDoubleQuote(name)}">
                            ${isCustomHtmlSelect ? cctCustomSelectOptionsBuilder(data.html, id, selectOptions) : data.html}
                        </div>
                        ${retiredLabelHtml}
                        %globals_asset_data_attributes:${id}^json_decode^index:description^index:value^neq::<div class="small text-muted mt-2">{globals_asset_data_attributes:${id}^json_decode^index:description^index:value}</div>%
                    </td>
                </tr>
            `;
    
    return html;
}


//##SECTION HTML

interface SectionHtmlData {
    id: string | number;
    fields?: FieldHtmlData[];
    activeHeading?: string | number;
    toggleAnimation?: boolean;
    extraClass?: string;
    toggle?: boolean;
    sort?: boolean;
    sortRef?: string | number;
}

const cctSectionHtml = (
    data: SectionHtmlData, 
    sectionHeading: boolean
): string => {
    
    const fields = objQuery(() => data.fields) || [];
    const id = data.id.toString();
    const sectionNameNoEndNumber = `%globals_asset_name:${id}^replace:[0-9 -]+$:^escapehtml%`;
    
    // Safely look up the active heading value from the store map
    const activeHeadingKey = data.activeHeading ? data.activeHeading.toString() : '';
    const storeActiveHeadingValue = store.metadataHashMap && activeHeadingKey 
        ? store.metadataHashMap[activeHeadingKey]?.value 
        : undefined;
    
    const activeHeadingStr = typeof storeActiveHeadingValue === 'string' ? storeActiveHeadingValue : '';
    const title = data.activeHeading && activeHeadingStr.trim().length 
        ? escapeHtml(activeHeadingStr) 
        : sectionNameNoEndNumber;
        
    //classes
    const toggleAnimationClass = "toggleAnimation" in data && data.toggleAnimation === false ? ` cct-no-toggle-animation` : ``;
    const extraClassData = objQuery(() => data.extraClass) ? ` ${data.extraClass}` : ``;
    const extraClass = extraClassData + toggleAnimationClass;

    //Accordion Variables
    const isToggle = objQuery(() => data.toggle) === true;     
    const toggleConfig = isToggle ? {
        elemTag                 : "button type='button'",
        accordionTriggerExtras  : ` sq-backend-section-subheading--accordion-trigger${toggleAnimationClass} align-items-center justify-content-between`,
        accordionAreaExtras     : ` sq-backend-section-inner-table-wrapper--accordion-area${toggleAnimationClass} hidden`,
    } : {
        elemTag                 : "div",
        accordionTriggerExtras  : "",
        accordionAreaExtras     : "",
    };
    // destructure 
    const { elemTag, accordionTriggerExtras, accordionAreaExtras } = toggleConfig;
    
    //Sort Variables
    const isSort = objQuery(() => data.sort) === true;
    const sortConfig = isSort ? {
        wrapperElem         : "td",
        wrapperClasses      : " class='sq-sortable-dragging__row'",
        sortRowStart        : `<tr class="sq-sortable-dragging${extraClass} cct-admin__section" data-sq-id="${id}" data-sortRef="${data.sortRef || ''}">`,
        sortRowEnd          : "</tr>",
        sortSectionTrigger  : `<div class="js_sq-draggable-column sq-draggable-column ui-sortable-handle position-absolute " title="Drag to reorder">
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="currentColor" >
                                        <use href="${iconSpriteAssetUrl}#cctDragHandle"></use>
                                    </svg>
                                </div>`,
    } : {
        wrapperElem         : `div data-sq-id="${id}"`,
        wrapperClasses      : ` class='cct-admin__section${extraClass}'`,
        sortRowStart        : "",
        sortRowEnd          : "",
        sortSectionTrigger  : "",
    };

    // destructure
    const { wrapperElem, wrapperClasses, sortRowStart, sortRowEnd, sortSectionTrigger } = sortConfig;

    //all fields html
    let fieldsHtml = '';
    fields.forEach((field) => {
        const fieldHtml = cctFieldHtml(field, data.activeHeading);
        fieldsHtml += fieldHtml;
    });
    
    // Splitting tags safely out of template literals to satisfy closing bracket structure
    const openWrapperTag = `<${wrapperElem}${wrapperClasses}>`;
    const closeWrapperTag = `</${wrapperElem.split(' ')[0]}>`;
    const openHeadingTag = `<${elemTag} data-default-content="${sectionNameNoEndNumber}" class="sq-backend-section-subheading d-flex${accordionTriggerExtras}">`;
    const closeHeadingTag = `</${elemTag.split(' ')[0]}>`;

    const html = `
            ${sortRowStart}
                ${openWrapperTag}
                    ${sortSectionTrigger}
                    ${sectionHeading ? `
                        ${openHeadingTag}
                            <span class="sq-backend-section-subheading__content">${title}</span>
                        ${closeHeadingTag}
                    ` : `` }
                    <div class="sq-backend-section-inner-table-wrapper p-0${accordionAreaExtras}">
                        <div class="px-4">
                            %globals_asset_data_attributes:${id}^json_decode^index:description^index:value^neq::<div class="sq-backend-note sq-text-normal pt-4 mt-0 mb-4">{globals_asset_data_attributes:${id}^json_decode^index:description^index:value}</div>%
                            <table class="sq-backend-section-table-inner">
                                <tbody>
                                    ${ fieldsHtml }
                                </tbody>
                            </table>
                        </div>
                    </div>
                ${closeWrapperTag}
            ${sortRowEnd}
        `;
    
    return html;
};


//##SORT TABLE HTML

const sortTableHtml = (unsortedGroup: Map<string, string>): string => {
    //start table
    let sortTable = `
        <table class="sq-backend-table js_sq-sortable-table sq-sortable-table sq-sortable-table--cct-control">
            <tbody class="ui-sortable">
    `;
        
        //table body
            // Safely parse the legacy V8 fallback for metadata parsing
            const rawMetadataValue = objQuery(() => store.asset.metadata['cct-control.section_sort'].value);
            let savedSortArray: string[] | false = false;

            if (typeof rawMetadataValue === 'string' && rawMetadataValue.trim().length) {
                try {
                    savedSortArray = JSON.parse(rawMetadataValue);
                } catch (e) {
                    savedSortArray = false;
                }
            }
            
            //Has custom sorting stored
            if (Array.isArray(savedSortArray)) {

                //metadata section existed in the last sort
                savedSortArray.forEach((key: string) => {
                  if (unsortedGroup.has(key)) {
                    sortTable += unsortedGroup.get(key);
                  }
                });
                
                //new metadata section added to schema after last sort
                const targetSavedArray = savedSortArray; // Local reference to satisfy compiler checking
                const newSections = [...unsortedGroup.keys()].filter(item => !targetSavedArray.includes(item));
                newSections.forEach((key: string) => {
                    sortTable += unsortedGroup.get(key) || '';
                });
                
            } else {
            //No custom sorting, first load (use default order as per the Custom Edit Layout asset order)
                 sortTable += Array.from(unsortedGroup.values()).join('');
            }
            
    //end table        
    sortTable += `
            </tbody>
        </table>
    `;
        
    return sortTable;
};


//##CCT BODY HTML

const cctBodyHtml = (): string => {
    let contentHtml = '';
    const unsortedGroup = new Map<string, string>();
    const sectionHeading = store.sections.length > 1;
    
    //All sections html
    store.sections.forEach((section) => {
        
        //generate this section html
        const sectionHtml = cctSectionHtml(section, sectionHeading);
        
        //add not sortable sections to return and split sortable sections in unsortedGroup
        const isSort = objQuery(() => section.sort) === true;
        if (isSort) {
            // Ensure sortRef is transformed to a valid string identifier for the Map key
            const sortKey = section.sortRef ? section.sortRef.toString() : section.id.toString();
            unsortedGroup.set(sortKey, sectionHtml);
        } else {
            //add not sortable sections to body html with their Custom Edit Layout order
            contentHtml += sectionHtml;
        }
    });
    
    if (unsortedGroup.size) {
        //Generate sort table HTML
        contentHtml += sortTableHtml(unsortedGroup);
    }
    
    const bodyHtml = `
        <div class="sq-backend-section-inner-table-wrapper">
            <div class="sq-backend-section-table-inner">
                ${contentHtml}    
            </div>    
        </div>        
    `;
    
    //return output
    return bodyHtml;
};


